module pulse_detect(
	input clk, rst_n, data_in,
	output reg data_out
	);

	reg [1:0] state;
	parameter s0 = 2'b00;
	parameter s1 = 2'b01;
	parameter s2 = 2'b10;
	parameter s3 = 2'b11;

	always@(posedge clk, negedge rst_n) 
	begin
		if(~rst_n) state <= s0;
		else begin
			case(state)
				s0: if(data_in == 1'b0) state <= s1;
					else 				state <= s0;
				s1: if(data_in == 1'b0) state <= s1;
					else 				state <= s2;
				s2: if(data_in == 1'b0) state <= s3;
					else 				state <= s0;
				s3: if(data_in == 1'b0) state <= s1;
					else 				state <= s0;
				default: state <= s0;
			endcase
		end
	end

	always@(*) begin
		data_out = (state == s2) && (data_in == 0);
	end
endmodule
